        html: `<p>Спадкоємець, який протягом шести місяців не подав заяву про прийняття спадщини, вважається таким, що <strong>не прийняв її</strong> (стаття 1272 Цивільного кодексу України). Його частка переходить до інших спадкоємців тієї самої черги, а за їх відсутності — до наступної черги. Саме тому «я не знав, що треба щось подавати» — найдорожча помилка у спадкових справах.</p>
<p>Важливо: правило не стосується тих, хто постійно проживав зі спадкодавцем на день смерті, а також малолітніх, неповнолітніх і недієздатних спадкоємців — вони вважаються такими, що прийняли спадщину автоматично. Перевірте свій статус до паніки: можливо, строк для вас взагалі не сплив. Загальну процедуру ми описали у статті <a href="/blog/oformlennya-spadshchyny/">про оформлення спадщини</a>.</p>`,
