        html: `<p>Спадкування за законом застосовується, коли заповіту немає, він визнаний недійсним, охоплює не все майно або спадкоємці за заповітом не прийняли спадщину чи усунені від неї (стаття 1258 Цивільного кодексу України). Закон вибудовує спадкоємців у <strong>п'ять черг</strong>, і кожна наступна отримує право на спадкування лише за відсутності спадкоємців попередньої черги, неприйняття ними спадщини, відмови або усунення.</p>
<p>Усередині однієї черги частки рівні (стаття 1267 ЦК України): троє дітей без інших спадкоємців першої черги отримають по 1/3. За домовленістю спадкоємці можуть змінити розподіл щодо рухомого майна усною угодою, а щодо нерухомості — письмовою, посвідченою нотаріально.</p>`,
