        html: `<p><strong>Усунення від спадкування</strong> (стаття 1224 ЦК України): не спадкують особи, які умисно позбавили життя спадкодавця чи спадкоємців, перешкоджали складенню заповіту, батьки, позбавлені батьківських прав, а за рішенням суду — ті, хто ухилявся від допомоги безпорадному спадкодавцеві. <strong>Відумерла спадщина</strong>: якщо спадкоємців немає взагалі або всі відмовилися, майно за заявою органу місцевого самоврядування переходить територіальній громаді (стаття 1277 ЦК України).</p>
<p>Практична порада: навіть якщо ви єдиний спадкоємець першої черги, не відкладайте візит до нотаріуса — <a href="/blog/oformlennya-spadshchyny/">заяву треба подати за 6 місяців</a>, інакше доведеться <a href="/blog/propushchenyy-strok-spadshchyna/">поновлювати строк</a>. А якщо черги конкурують — наприклад, цивільна дружина проти братів спадкодавця — без судового встановлення фактів не обійтися. Такі спори ми ведемо в межах послуги <a href="/practices/family-law/spadkovi-spravy-ta-spory-pro-spadshchynu/">«Спадкові справи та спори про спадщину»</a>; почати варто з <a href="/contacts/#consult">консультації</a>.</p>`,
