        h2: "У чому особливість аліментів із підприємця",
        html: `<p>Загальні правила однакові для всіх: аліменти на дитину стягуються у частці від доходу (стаття 183 Сімейного кодексу України) або у твердій грошовій сумі (стаття 184 СК України), а мінімальний розмір на одну дитину не може бути меншим за 50 відсотків прожиткового мінімуму для дитини відповідного віку. Проблема ФОП — в іншому: його дохід не фіксується роботодавцем, а визначається ним самим у звітності.</p>
<p>Саме тому справи про аліменти з підприємців — одні з найбільш «доказових» у сімейній практиці: результат залежить від того, наскільки якісно доведено реальний дохід платника. Базові механізми ми описали на сторінці послуги <a href="/practices/family-law/styahnennya-ta-zmina-rozmiru-alimentiv/">«Стягнення та зміна розміру аліментів»</a>.</p>`,
