<p>Якщо особа зникла безвісти в умовах бойових дій, це окремий правовий статус з власною процедурою, і він впливає не лише на розлучення, а й на майнові питання. Про нього ми пишемо в матеріалі про <a href="/blog/znyklyy-bezvisty-status/">статус зниклого безвісти</a>.</p>
