        h2: "Куди подавати виконавчий документ",
        html: `<p>Є два шляхи, і другий на практиці працює швидше.</p>
<ol>
<li><b>До органу державної виконавчої служби або приватного виконавця.</b> Класичний варіант: виконавець сам встановлює місце служби й надсилає документи.</li>
<li><b>Безпосередньо до військової частини.</b> Стягувач має право подати виконавчий документ за місцем отримання доходу напряму — тоді фінансовий орган частини утримує аліменти без участі виконавця.</li>
</ol>
<p>Другий шлях економить час, але потребує знання точної адреси частини та її реквізитів. Крім того, при переведенні військовослужбовця документи доводиться пересилати — виконавець робить це автоматично, а стягувач має стежити самостійно.</p>
<p>Розумний компроміс — відкрити виконавче провадження, а копію документа продублювати до частини.</p>`,
