        html: `<p>Аліменти можуть стягуватися часткою від доходу або у твердій грошовій сумі. Для військовослужбовців вибір має практичне значення.</p>
<p><b>Частка</b> вигідна, коли забезпечення стабільне й високе: сума автоматично зростає разом із доходом, не потребуючи звернення до суду.</p>
<p><b>Тверда сума</b> дає передбачуваність і не залежить від структури виплат — вона знімає всі спори про те, з чого саме утримувати. Її обирають, коли дохід нерегулярний або коли платник змінює місце служби. Детальніше — у матеріалі про <a href="/blog/alimenty-tverda-groshova-suma/">аліменти у твердій грошовій сумі</a>.</p>
<p>Незалежно від способу діє правило про мінімальний розмір аліментів на одну дитину — суд не може присудити менше, ніж встановлено законом.</p>`,
