        h2: "Якщо аліменти не надходять",
        html: `<p>Найчастіша причина — не ухилення, а звичайна логістика: частина не отримала виконавчий документ, або він «загубився» при переведенні. Тому перший крок завжди однаковий: з’ясувати, чи дійшов документ до фінансового органу.</p>
<p>Якщо документ отриманий, а виплат немає — подається заява виконавцю про розрахунок заборгованості. На підставі цього розрахунку застосовуються загальні механізми: пеня, обмеження прав боржника, стягнення на майно. Про них ми пишемо в матеріалі про <a href="/blog/alimenty-zaborhovanist/">заборгованість за аліментами</a>.</p>
<p>Окремо варто зазначити: наявність аліментного боргу сама по собі не є підставою для звільнення зі служби чи інших спеціальних наслідків. Механізми стягнення тут ті самі, що й для будь-якого іншого боржника.</p>
<p>Адвокати практики <a href="/practices/family-law/">сімейного права LEGIUS</a> супроводжують стягнення аліментів, зокрема у справах, де платник проходить військову службу.</p>`,
