        h2: "Як визначається розмір",
        html: `<p>Суд не бере цифру зі стелі й не задовольняє будь-яку заявлену суму. Він зважує кілька обставин: стан здоров’я та матеріальне становище дитини, матеріальне становище платника, наявність у нього інших дітей та осіб на утриманні, а також інші обставини, що мають істотне значення.</p>
<p>Дві межі, які варто знати:</p>
<ul>
<li><b>Мінімум.</b> Розмір аліментів на одну дитину не може бути меншим за половину прожиткового мінімуму для дитини відповідного віку. Це гарантована нижня межа.</li>
<li><b>Орієнтир.</b> Закон окремо називає рекомендований розмір — повний прожитковий мінімум для дитини відповідного віку. Це не обов’язок суду, а орієнтир, до якого варто прагнути в обґрунтуванні.</li>
</ul>
<p>Оскільки прожитковий мінімум різниться за віковими групами й переглядається, конкретні суми перед подачею позову слід звіряти з чинними показниками.</p>`,
