        html: `<p>Заборона одна, і вона стосується лише чоловіка. Позов про розірвання шлюбу не може бути пред’явлений <b>чоловіком</b> протягом вагітності дружини та протягом одного року після народження дитини.</p>
<p>Винятки з цього правила існують, але вони вузькі й потребують доведення конкретних обставин. Для дружини такого обмеження немає — вона може подати позов у будь-який час.</p>
<p>Інших підстав, за яких суд може відмовити в розірванні шлюбу назавжди, законодавство не містить. Твердження «я не дам розлучення» правового значення не має.</p>
<p>Адвокати практики <a href="/practices/family-law/">сімейного права LEGIUS</a> ведуть справи про розірвання шлюбу, зокрема в конфліктних процесах із запереченням і затягуванням.</p>`,
